use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl RealFileName { # [doc = " Returns the path suitable for reading from the file system on the local host,"] # [doc = " if this information exists."] # [doc = " Avoid embedding this in build artifacts; see `remapped_path_if_available()` for that."] pub fn local_path (& self) -> Option < & Path > { match self { RealFileName :: LocalPath (p) => Some (p) , RealFileName :: Remapped { local_path , virtual_name : _ , } => local_path . as_deref () , } } # [doc = " Returns the path suitable for reading from the file system on the local host,"] # [doc = " if this information exists."] # [doc = " Avoid embedding this in build artifacts; see `remapped_path_if_available()` for that."] pub fn into_local_path (self) -> Option < PathBuf > { match self { RealFileName :: LocalPath (p) => Some (p) , RealFileName :: Remapped { local_path : p , virtual_name : _ , } => p , } } # [doc = " Returns the path suitable for embedding into build artifacts. This would still"] # [doc = " be a local path if it has not been remapped. A remapped path will not correspond"] # [doc = " to a valid file system path: see `local_path_if_available()` for something that"] # [doc = " is more likely to return paths into the local host file system."] pub fn remapped_path_if_available (& self) -> & Path { match self { RealFileName :: LocalPath (p) | RealFileName :: Remapped { local_path : _ , virtual_name : p , } => p , } } # [doc = " Returns the path suitable for reading from the file system on the local host,"] # [doc = " if this information exists. Otherwise returns the remapped name."] # [doc = " Avoid embedding this in build artifacts; see `remapped_path_if_available()` for that."] pub fn local_path_if_available (& self) -> & Path { match self { RealFileName :: LocalPath (path) | RealFileName :: Remapped { local_path : None , virtual_name : path , } | RealFileName :: Remapped { local_path : Some (path) , virtual_name : _ , } => path , } } # [doc = " Return the path remapped or not depending on the [`FileNameDisplayPreference`]."] # [doc = ""] # [doc = " For the purpose of this function, local and short preference are equal."] pub fn to_path (& self , display_pref : FileNameDisplayPreference) -> & Path { match display_pref { FileNameDisplayPreference :: Local | FileNameDisplayPreference :: Short => { self . local_path_if_available () } FileNameDisplayPreference :: Remapped => self . remapped_path_if_available () , } } pub fn to_string_lossy (& self , display_pref : FileNameDisplayPreference) -> Cow < '_ , str > { match display_pref { FileNameDisplayPreference :: Local => self . local_path_if_available () . to_string_lossy () , FileNameDisplayPreference :: Remapped => { self . remapped_path_if_available () . to_string_lossy () } FileNameDisplayPreference :: Short => self . local_path_if_available () . file_name () . map_or_else (| | "" . into () , | f | f . to_string_lossy ()) , } } }